G = nx.Graph()
G.add_edges_from(edges)

def get_girth(G):
    girth = float('inf')
    for n in G.nodes():
        # BFS to find shortest cycle
        queue = [(n, [n])]
        while queue:
            curr, path = queue.pop(0)
            for neighbor in G.neighbors(curr):
                if neighbor == path[-1]:
                    continue
                if len(path) > 1 and neighbor == path[-2]:
                    continue
                if neighbor in path:
                    cycle_len = len(path) - path.index(neighbor)
                    if cycle_len < girth:
                        girth = cycle_len
                else:
                    queue.append((neighbor, path + [neighbor]))
    return girth

print("Girth:", get_girth(G))
print("Degrees:", [d for n, d in G.degree()])

